node -e "
const initSqlJs = require('sql.js');
const fs = require('fs');
initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);
  // Get tables
  const tables = db.exec(\"SELECT name FROM sqlite_master WHERE type='table'\");
  console.log('Tables:', JSON.stringify(tables[0].values));
});
"

node -e "
const initSqlJs = require('sql.js');
const fs = require('fs');
initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);
  // Get schema
  const schema = db.exec(\"PRAGMA table_info(products)\");
  console.log('Columns:', JSON.stringify(schema[0].values));
  // Query product
  const result = db.exec(\"SELECT * FROM products WHERE product_code = 'PROD-FA0948'\");
  console.log('Columns:', JSON.stringify(schema[0].columns));
  console.log('Data:', JSON.stringify(result[0].values));
});
"

